import{_ as t,o,c as n,a0 as s}from"./chunks/framework.C3yZ6M33.js";const p=JSON.parse('{"title":"Queue & supersede policy","description":"","frontmatter":{},"headers":[],"relativePath":"reference/queue-supersede.md","filePath":"reference/queue-supersede.md"}'),i={name:"reference/queue-supersede.md"};function r(a,e,d,c,l,u){return o(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="queue-supersede-policy" tabindex="-1">Queue &amp; supersede policy <a class="header-anchor" href="#queue-supersede-policy" aria-label="Permalink to &quot;Queue &amp; supersede policy&quot;">​</a></h1><p>The engine executes <strong>one</strong> run at a time; the supersede policy decides <em>which</em> runs happen when trigger events outpace the executor. This is node-level policy, not engine internals — it lives in <code>peregrin-queue</code> (pure logic, no I/O) and the node daemon drives it around each <code>Runner</code>. The <code>peregrin-node</code> <code>RunSupervisor</code> composes the queue with the engine&#39;s ingress channel into the sequential run loop the daemon will own.</p><h2 id="supersede-campaign-config" tabindex="-1"><code>supersede:</code> campaign config <a class="header-anchor" href="#supersede-campaign-config" aria-label="Permalink to &quot;`supersede:` campaign config&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">supersede</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{repo}:{ref}&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # template over the trigger event payload</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">latest-wins</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # | fifo</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  cancel_running</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # cancel the active run vs queue behind it</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>key</code></td><td>template</td><td><code>&quot;&quot;</code></td><td><code>{dotted.path}</code> placeholders resolved against the trigger event&#39;s <code>payload</code>; events resolving to the same key are alternative triggers for the same logical run (one branch, one PR, one WAL head). Empty = a constant key, so every event targets the same run.</td></tr><tr><td><code>mode</code></td><td><code>latest-wins</code> | <code>fifo</code></td><td><code>latest-wins</code></td><td>Pending-job dedupe: <code>latest-wins</code> replaces the pending job that shares the key (only the newest trigger for a target runs — the displaced job&#39;s queue <em>position</em> is inherited); <code>fifo</code> appends (every trigger runs) up to <code>MAX_PENDING_PER_KEY</code> (32) per key — beyond that the key&#39;s <em>oldest</em> pending job is evicted.</td></tr><tr><td><code>cancel_running</code></td><td>bool</td><td><code>false</code></td><td><code>true</code>: a new event marks the <em>active</em> run superseded — the queue raises a one-shot cancel signal the caller delivers to the run. <code>false</code>: new events always queue behind the active run.</td></tr></tbody></table><h2 id="key-template-grammar" tabindex="-1">Key template grammar <a class="header-anchor" href="#key-template-grammar" aria-label="Permalink to &quot;Key template grammar&quot;">​</a></h2><p>Distinct from <code>${...}</code> scope resolution — the <code>{path}</code> grammar is a small payload-only interpolation:</p><ul><li><code>{repo}</code>, <code>{origin.ref}</code> — dotted-path walk over <code>event.payload</code>, one key per <code>.</code> segment.</li><li>Values stringify like JS: <code>null</code> → <code>&quot;null&quot;</code>, numbers/booleans as <code>String(v)</code>, arrays join with <code>,</code>, objects → <code>&quot;[object Object]&quot;</code>.</li><li>A miss — absent key, non-object step, empty or unclosed placeholder, an interior containing <code>{</code> — stays <strong>verbatim</strong> (<code>{missing}</code> in the key is a literal, still deterministic).</li><li><code>&amp;#123;&amp;#123;</code> emits a literal <code>{</code> and rescans: <code>&amp;#123;&amp;#123;repo&amp;#125;&amp;#125;</code> → <code>{a/b}</code>.</li></ul><h2 id="queue-semantics" tabindex="-1">Queue semantics <a class="header-anchor" href="#queue-semantics" aria-label="Permalink to &quot;Queue semantics&quot;">​</a></h2><p><code>Queue::submit(event)</code> resolves the key and returns a <code>Decision</code> (<code>key</code>, <code>disposition</code>, <code>cancel_active</code>):</p><ul><li><strong>Dedupe</strong> applies to <em>pending</em> jobs only — under <code>latest-wins</code> the new event replaces the same-key pending job in place and the displaced <code>Job</code> comes back in <code>Disposition::ReplacedPending(job)</code> for observability. The <em>active</em> run is never deduped: same-key events while it runs queue another run (or cancel it, with <code>cancel_running</code>).</li><li><strong>Cancel</strong> is a one-shot signal: the first <code>cancel_running</code> submit while a run is active reports <code>cancel_active</code> and stashes the superseded <code>Job</code>, handed out once by <code>take_cancel()</code>. <code>finish()</code> clears an unread signal — a run that ended is moot to cancel.</li><li><strong>Drain</strong> is sequential (the gate case): <code>drain()</code> returns <code>None</code> while a job is active and otherwise pops the front job and marks it active; <code>finish()</code> releases the slot. Pending jobs iterate in drain order via <code>pending()</code>.</li></ul><h2 id="ingress-injection-channel" tabindex="-1">Ingress injection channel <a class="header-anchor" href="#ingress-injection-channel" aria-label="Permalink to &quot;Ingress injection channel&quot;">​</a></h2><p>External events can&#39;t call <code>LocalBus::publish</code> directly — it&#39;s <code>&amp;mut</code> and the runner is single-threaded, so a blocking producer (a webhook listener, a WAL poller) would stall the loop (audit I-014). The channel splits that (<code>peregrin-engine</code>, <code>std::sync::mpsc</code> — the engine is synchronous):</p><ul><li><code>peregrin_engine::ingress()</code> returns <code>(Injector, Ingress)</code>.</li><li><strong><code>Injector</code></strong> is the <code>Send + Sync</code>, cloneable producer half — any thread or spawned ingress driver pushes <code>Event</code>s without <code>&amp;mut</code> access to anything. <code>inject</code> fails with <code>InjectError</code> (carrying the event back) once the run&#39;s receiver is dropped.</li><li><strong><code>Ingress</code></strong> is the runner&#39;s receiver — <code>Runner::with_ingress</code> attaches it and the run loop drains it into <code>pending</code> once per iteration.</li></ul><p>Ordering guarantee: injected events serialize <strong>after</strong> every event already pending at the drain — including the triggers of the step currently executing — and <strong>before</strong> anything nodes emit afterward. A <code>workflow.cancel</code> pushed through the injector is honored at the next iteration boundary, exactly like a node-emitted one (it is consumed by the loop, not published — the log shows <code>workflow.cancelled</code>).</p><p>Two edge rulings:</p><ul><li>Events pushed <strong>before</strong> <code>run()</code> starts are delivered — the runner drains on the first iteration too (<code>RunSupervisor</code> uses this to deliver the trigger event itself).</li><li>Events arriving while the <em>last</em> step executes still land: the loop drains <strong>before</strong> its exit check, so only an event arriving after the final iteration can be dropped — a quiescent run exits; the channel does not keep it alive.</li></ul><h2 id="runsupervisor-composition" tabindex="-1"><code>RunSupervisor</code> composition <a class="header-anchor" href="#runsupervisor-composition" aria-label="Permalink to &quot;`RunSupervisor` composition&quot;">​</a></h2><p><code>peregrin_node::supervisor::RunSupervisor</code> is the composable wrapper the daemon drives: <code>submit(event)</code> → <code>SubmitOutcome { decision, start, cancelled_active }</code>; <code>finish()</code> → <code>Option&lt;PendingRun&gt;</code>.</p><ul><li><code>start</code> is <code>Some(PendingRun)</code> only when no run is active — it carries a fresh <code>(injector, ingress)</code> pair for its run with the trigger event already queued on it; hand <code>ingress</code> to <code>Runner::with_ingress</code>, clone <code>injector</code> for external producers.</li><li>Under <code>cancel_running</code>, a superseding submit pushes <code>Event::cancel(&quot;superseded by a newer trigger for key &#39;&lt;key&gt;&#39;&quot;)</code> into the active run&#39;s own ingress channel — the cancellation surface the single-threaded runner actually honors.</li><li>The runner itself stays <code>!Send</code> (Rc internals) — runs execute on the loop thread; the channel is the entire cross-thread input surface.</li></ul><h2 id="durable-queue-queue-store" tabindex="-1">Durable queue (<code>--queue-store</code>) <a class="header-anchor" href="#durable-queue-queue-store" aria-label="Permalink to &quot;Durable queue (`--queue-store`)&quot;">​</a></h2><p>Without a store the queue is memory-only — a restart loses every pending trigger. <code>campaign run --queue-store &lt;path&gt;</code> (supervisor mode only) opens a sqlite <code>QueueStore</code> (<code>peregrin-queue-sqlite</code>) and makes the queue durable:</p><ul><li><strong>What persists</strong> — pending submissions grouped by supersede key (per-key writes, so peers never clobber each other) plus the in-flight marker. Written through on every submit/drain/finish.</li><li><strong>What replays</strong> — on boot, <code>RunSupervisor::with_store</code> loads the snapshot and runs it through <code>Queue::restore</code> <em>before</em> the loop accepts new triggers: pending jobs restore in drain order and the interrupted run&#39;s marker re-queues at the <strong>front</strong> (at-least-once — it gets another shot). Under <code>latest-wins</code> a newer same-key pending entry still supersedes it, exactly as live.</li><li><strong>Re-validation</strong> — persisted rows aren&#39;t a trust boundary: each entry&#39;s stored key must match <code>policy.key_of(event)</code> (a changed <code>supersede:</code> block or corrupt row drops it, logged), and restored entries go through the same dedupe/bound path as live submits, so a restored queue can&#39;t hold a state submits couldn&#39;t produce.</li><li><strong>Failure policy</strong> — an unreadable store fails the boot (queued triggers would be silently lost otherwise); per-entry corruption is skipped with a warning; write failures mid-run are logged and degrade durability rather than killing runs.</li></ul><p>The store file is ordinary sqlite — <code>queue_pending(key, seq, job)</code> rows plus a singleton <code>queue_running</code> row; safe to inspect with <code>sqlite3</code>.</p><p>Under <code>peregrin campaign serve --queue-store-dir &lt;dir&gt;</code> each hosted campaign gets its own store at <code>&lt;dir&gt;/&lt;campaign&gt;.db</code> — same schema, same semantics, independent namespaces. Likewise <code>--history-dir</code> namespaces run history as <code>&lt;dir&gt;/&lt;campaign&gt;.jsonl</code>. See <a href="./../how-to/serve-campaigns.html">Serve a fleet of campaigns</a>.</p>',25)])])}const g=t(i,[["render",r]]);export{p as __pageData,g as default};
